@@ -7396,8 +7396,18 @@ static void tg3_napi_disable(struct tg3 *tp)
        int txq_idx = tp->txq_cnt - 1;
        int rxq_idx = tp->rxq_cnt - 1;
        struct tg3_napi *tnapi;
