diff --git a/mm/swapfile.c b/mm/swapfile.c
index 08309c1dafa3..46caad0013b9 100644
--- a/mm/swapfile.c
+++ b/mm/swapfile.c
@@ -1443,8 +1443,10 @@ static bool swap_sync_discard(void)
