+static int pmb_retry_reattach(int map_fd, __u32 key, int sock_fd)
+{
+ unsigned int attempt;
+ __u64 value = sock_fd;
+
+ for (attempt = 0; attempt < 200000; attempt++) {
+ if (!bpf_map_update_elem(map_fd, &key, &value, BPF_NOEXIST))
+ return 0;
+ if (errno != EEXIST && errno != EBUSY)
+ return -errno;
+ sched_yield();
+ }
+
+ return -ETIMEDOUT;
+}
