  ext4  io_uring       1     18,882        18,897        +0.08%
  ext4  io_uring       64    552,607       576,712       +4.36%
  ext4  io_uring       256   552,330       576,603       +4.39%
  ext4  io_uring       1024  557,330       584,227       +4.83%
