+	default:
+		dev_err(dev, "Unknown discovery source: %d\n", ivdev->src);
+		return -EINVAL;
+	}
+
 	entry->guid = header->guid;
 	entry->size = header->size;
 	entry->cb = ivdev->priv_data;
@@ -370,21 +445,54 @@ static int intel_pmt_dev_register(struct intel_pmt_entry *entry,
 	return ret;
